//! Measured GEMM/BLAS solution-override tables (astrum P1).
//!
//! Loads an offline-tuned table pinning the winning solution index per
//! (M-bucket, N, K, arch, arith, library). Tables are generated by a
//! measurement harness and guarded by a runtime library/arch version check so a
//! stale table never silently applies wrong solution IDs.
//!
//! Env:
//! - `GRIM_ASTRUM_BLASLT_TABLE`: path to a blaslt measured table (JSON).
//! - `GRIM_ASTRUM_ROCBLAS_TABLE`: path to a rocblas measured table (JSON).
//!
//! Default OFF: when unset/unloadable/mismatched, callers fall through to the
//! existing hand-seeded tables (bit-identical default behavior).

use crate::device::blaslt::BlasLtProbe;
use grim_tensor::ArithType;
use serde::{Deserialize, Serialize};
use std::sync::OnceLock;

/// A single measured (shape, variant) winner.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct MeasuredEntry {
    pub m: usize,
    pub n: usize,
    pub k: usize,
    /// Arithmetic as a lowercase string: "f32", "f16", "bf16", "i64", "u32", "u8".
    pub arith: String,
    pub solution: i32,
    pub speedup: f64,
}

/// Measured solution table for one (arch, library build).
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct MeasuredTable {
    pub arch: String,
    /// "blaslt" or "rocblas" (defaults to "blaslt" for plan compatibility).
    #[serde(default = "default_library")]
    pub library: String,
    /// Version string reported by the runtime probe (compared for equality).
    #[serde(default)]
    pub blaslt_version: String,
    #[serde(default)]
    pub entries: Vec<MeasuredEntry>,
}

fn default_library() -> String {
    "blaslt".to_string()
}

fn arith_name(arith: ArithType) -> &'static str {
    match arith {
        ArithType::F32 => "f32",
        ArithType::F16 => "f16",
        ArithType::BF16 => "bf16",
        ArithType::I64 => "i64",
        ArithType::U32 => "u32",
        ArithType::U8 => "u8",
    }
}

/// M bucket: exact for m <= 8, else next power-of-two ceiling (>= 8).
pub fn m_bucket(m: usize) -> usize {
    if m <= 8 {
        m
    } else {
        m.next_power_of_two()
    }
}

/// Load a measured table from a JSON file.
pub fn load_measured_table(path: &str) -> Result<MeasuredTable, String> {
    let text = std::fs::read_to_string(path)
        .map_err(|e| format!("read measured table {path}: {e}"))?;
    serde_json::from_str(&text).map_err(|e| format!("parse measured table {path}: {e}"))
}

/// Lookup a measured solution. Returns `Some(solution_index)` on an exact
/// (library-agnostic within the table) shape+arch+arith hit after M bucketing,
/// else `None` (caller must fall through to hand-seeded/default behavior).
pub fn lookup_measured_solution(
    table: &MeasuredTable,
    m: usize,
    n: usize,
    k: usize,
    arch: &str,
    arith: ArithType,
) -> Option<i32> {
    if !table.arch.eq_ignore_ascii_case(arch) {
        return None;
    }
    let want_m = m_bucket(m);
    let want_arith = arith_name(arith);
    table
        .entries
        .iter()
        .find(|e| {
            e.n == n
                && e.k == k
                && e.arith.eq_ignore_ascii_case(want_arith)
                && m_bucket(e.m) == want_m
        })
        .map(|e| e.solution)
}

/// Compare a table's recorded version against an explicit probe version string.
pub fn table_version_guard_str(table: &MeasuredTable, probe_version: &str) -> bool {
    table.blaslt_version == probe_version
}

/// Compare a table's recorded version against a blaslt probe.
pub fn table_version_matches_probe(table: &MeasuredTable, probe: &BlasLtProbe) -> bool {
    match probe.version {
        Some(v) => table_version_guard_str(table, &v.to_string())
            // also accept the full describe() string for tables recorded that way
            || table_version_guard_str(table, &probe.describe()),
        None => false,
    }
}

fn load_table_once(env_var: &'static str, expected_library: &'static str) -> Option<MeasuredTable> {
    let path = std::env::var(env_var).ok()?;
    let table = match load_measured_table(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("[astrum] {env_var} load failed: {e}");
            return None;
        }
    };
    if !table.library.eq_ignore_ascii_case(expected_library) {
        eprintln!(
            "[astrum] {env_var}: library mismatch (table={}, expected={expected_library}), ignoring",
            table.library
        );
        return None;
    }
    eprintln!(
        "[astrum] measured table: {path} (lib={}, arch={}, {} entries)",
        table.library,
        table.arch,
        table.entries.len()
    );
    Some(table)
}

static BLASLT_TABLE: OnceLock<Option<MeasuredTable>> = OnceLock::new();
static ROCBLAS_TABLE: OnceLock<Option<MeasuredTable>> = OnceLock::new();

/// Cached blaslt measured table (`GRIM_ASTRUM_BLASLT_TABLE`), loaded once.
pub fn blaslt_measured_table() -> Option<&'static MeasuredTable> {
    BLASLT_TABLE
        .get_or_init(|| load_table_once("GRIM_ASTRUM_BLASLT_TABLE", "blaslt"))
        .as_ref()
}

/// Cached rocblas measured table (`GRIM_ASTRUM_ROCBLAS_TABLE`), loaded once.
pub fn rocblas_measured_table() -> Option<&'static MeasuredTable> {
    ROCBLAS_TABLE
        .get_or_init(|| load_table_once("GRIM_ASTRUM_ROCBLAS_TABLE", "rocblas"))
        .as_ref()
}

/// Lookup a blaslt solution override for `(m,n,k,arch,arith)` from the
/// env-configured measured table. Returns `None` when no table is configured,
/// the table mismatches, or no entry hits — callers fall through to defaults.
pub fn lookup_measured_blaslt_solution(
    m: usize,
    n: usize,
    k: usize,
    arch: &str,
    arith: ArithType,
) -> Option<i32> {
    let table = blaslt_measured_table()?;
    lookup_measured_solution(table, m, n, k, arch, arith)
}

/// Lookup a rocblas solution override (only from a `library="rocblas"` table).
pub fn lookup_measured_rocblas_solution(
    m: usize,
    n: usize,
    k: usize,
    arch: &str,
    arith: ArithType,
) -> Option<i32> {
    let table = rocblas_measured_table()?;
    lookup_measured_solution(table, m, n, k, arch, arith)
}
